/* Collapsed by default — just an icon button. Click expands to a 16rem input.
 * Stays expanded while the input has text (controlled by React).
 * Open chrome matches the filter pills (same control height, 1px border,
 * full radius) so a row of header controls reads as one family; the border
 * is reserved while collapsed so expanding does not shift layout. */
.search-input {
  display: flex;
  align-items: center;
  height: var(--control-height);
  width: var(--control-height);            /* collapsed: just an icon button */
  border: 1px solid transparent;
  /* --control-radius, not --radius-full: the shape is the brand's decision, and
   * hard-coding the pill here meant a rebrand to square controls left the
   * search a lozenge in a row of rectangles. */
  border-radius: var(--control-radius);
  background: transparent;
  overflow: hidden;
  transition: width var(--duration-normal) ease, background var(--duration-normal) ease,
    border-color var(--duration-fast);
}
/* --muted surface: the open --card fill separates it, so drop the open border. */
.search-input[data-surface="muted"][data-open] { border-color: transparent; }
.search-input[data-open] {
  /* Component-private knob: a header whose search is the primary control can
   * widen it (`.my-header .search-input { --search-expanded-width: 26rem }`)
   * without forking the component. */
  width: var(--search-expanded-width, 16rem);
  background: var(--card);
  border-color: var(--border);
}

.search-input-toggle {
  flex-shrink: 0;
  display: grid;
  place-items: center;
  width: var(--control-height);
  height: 100%;
  padding: 0;
  border: none;
  background: transparent;
  color: var(--muted-foreground);
  font-family: inherit;
  cursor: pointer;
  transition: color var(--duration-fast);
}
.search-input-toggle:hover { color: var(--foreground); }
/* Pressed: one stop past hover, the third answer every control now gives. */
.search-input-toggle:active,
.search-input-clear:active { color: var(--primary-accent); }
.search-input[data-open] .search-input-toggle { cursor: default; pointer-events: none; }

.search-input-field {
  flex: 1;
  min-width: 0;
  height: 100%;
  border: none;
  outline: none;
  background: transparent;
  color: var(--foreground);
  font-family: inherit;
  font-size: var(--font-base);
  /* A placeholder (or value) longer than the field trails off in an ellipsis
   * instead of being cut mid-letter at the edge. */
  text-overflow: ellipsis;
  opacity: 0;
  transition: opacity var(--duration-fast) 60ms;
}
.search-input[data-open] .search-input-field { opacity: 1; }
.search-input-field::placeholder { color: var(--muted-foreground); }
/* Hide native search clear button (we render our own) */
.search-input-field::-webkit-search-cancel-button { -webkit-appearance: none; appearance: none; }

.search-input-clear {
  flex-shrink: 0;
  display: grid;
  place-items: center;
  width: var(--control-height);
  height: 100%;
  padding: 0;
  border: none;
  background: transparent;
  color: var(--muted-foreground);
  font-family: inherit;
  cursor: pointer;
  transition: color var(--duration-fast);
}
.search-input-clear:hover { color: var(--foreground); }
.search-input-clear:focus-visible {
  outline: var(--ring-width) solid var(--ring);
  outline-offset: calc(-1 * var(--ring-offset));
  border-radius: var(--radius-full);
}

/* The ring, drawn INSIDE. The note that used to sit here was right about the
 * cost — an outer ring made the open search taller than the filter pills beside
 * it — and wrong about the fix: dropping to a 1px border recolour left the one
 * field in the system whose focus was thinner than everywhere else, under the
 * 2px perimeter SC 2.4.11 asks for. A negative offset gives the full ring and
 * changes no dimension, which is what the original objection actually wanted. */
.search-input[data-open]:focus-within {
  border-color: var(--primary-accent);
  outline: var(--ring-width) solid var(--ring);
  outline-offset: calc(-1 * var(--ring-offset));
}
/* Collapsed state is a plain icon button; keep a visible keyboard focus. */
.search-input-toggle:focus-visible {
  outline: var(--ring-width) solid var(--ring);
  /* --ring-offset, not --ring-width: the two happen to be the same number today,
   * so this read as correct and would have drifted the moment either knob moved.
   * Inset is the shape; the offset token is the value. */
  outline-offset: calc(-1 * var(--ring-offset));
  border-radius: var(--radius-full);
}

import './SearchInput.css'
import { useRef, useState, type FocusEvent, type InputHTMLAttributes } from 'react'
import { useTranslation } from 'react-i18next'
import { cn } from '../lib/cn'
import { Icon } from '../Icon'

type Props = InputHTMLAttributes<HTMLInputElement> & {
  /** Which surface the field sits on. On `muted` (a page/PageHeader) the border
   *  is dropped since the white fill separates it; `base` (default, a white card
   *  or form) keeps the border. Invalid + focus stay visible on both. */
  surface?: 'base' | 'muted'
  /** Called when the user clicks the clear (×) button. Parent owns the value. */
  onClear?: () => void
  /** Always-open, persistent field (no collapse-to-icon). For panels/forms where
   * the search is a permanent control; width comes from `className`. */
  expanded?: boolean
}

/**
 * The search field: the icon, the clear button and the debounce contract in
 * one control.
 *
 * Copy: the placeholder names the field being searched — "Search invoices" — so
 * a screen with two searches is two different controls.
 */
export function SearchInput({ className, value, onBlur, onClear, expanded, surface = 'base', ...rest }: Props) {
  const { t } = useTranslation()
  const hasValue = Boolean(value && String(value).length > 0)
  const [open, setOpen] = useState(hasValue)
  const inputRef = useRef<HTMLInputElement>(null)
  const isOpen = expanded || open || hasValue
  /* Expanded: the × only clears text (there is nothing to collapse to), so it
   * shows only with a value. Collapsible: × doubles as close, shown while open. */
  const showClear = expanded ? hasValue : isOpen

  const expand = () => {
    setOpen(true)
    /* Focus after the input becomes visible. flushSync + ref would be cleaner
     * but rAF is enough for this single-paint transition. */
    requestAnimationFrame(() => inputRef.current?.focus())
  }

  const handleBlur = (e: FocusEvent<HTMLInputElement>) => {
    if (!expanded && !e.currentTarget.value) setOpen(false)
    onBlur?.(e)
  }

  /* X button = clear text; on the collapsible variant it also collapses back. */
  const handleClose = () => {
    onClear?.()
    if (!expanded) setOpen(false)
  }

  return (
    <div className={cn('search-input', className)} data-open={isOpen || undefined} data-surface={surface}>
      <button
        type="button"
        className="search-input-toggle"
        aria-label={t('a11y.search')}
        tabIndex={isOpen ? -1 : 0}
        onClick={isOpen ? undefined : expand}
      >
        <Icon name="search" />
      </button>
      {/* A SEARCH BOX IS NEVER A CREDENTIAL FIELD, and it has to say so: a page
          holding any password field is a sign-in to a browser, which then fills
          the nearest username-ish box from its saved accounts. The components
          page filled its own search with a person's name the moment the
          PasswordInput example opened (owner, 2026-08-24). Stated here rather
          than at each call site, because every search in the system has it. */}
      <input
        ref={inputRef}
        type="search"
        autoComplete="off"
        className="search-input-field"
        value={value}
        onBlur={handleBlur}
        tabIndex={isOpen ? 0 : -1}
        {...rest}
      />
      {showClear && (
        <button
          type="button"
          className="search-input-clear"
          aria-label={t('a11y.clear')}
          /* mousedown (not click) so it fires before the input's blur collapses it. */
          onMouseDown={(e) => { e.preventDefault(); handleClose() }}
        >
          <Icon name="close" />
        </button>
      )}
    </div>
  )
}
